import{_ as i,l as d,o as a,c as l,v as r,p as c,x as o,d as n,i as s,S as E}from"./chunks/framework.InCnrqk-.js";const g=JSON.parse('{"title":"生命周期与悬挂","description":"","frontmatter":{"title":"生命周期与悬挂","date":"2026-09-10T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/lifetime-dangling.md","filePath":"cs/lifetime-dangling.md","lastUpdated":1789023840000}'),p={name:"cs/lifetime-dangling.md"};function f(h,e,m,A,B,u){const t=d("Mermaid");return a(),l("div",null,[e[1]||(e[1]=r('<h1 id="生命周期与悬挂" tabindex="-1">生命周期与悬挂 <a class="header-anchor" href="#生命周期与悬挂" aria-label="Permalink to &quot;生命周期与悬挂&quot;">​</a></h1><div class="epigraph"><p>指针的值可以比它所指数的对象活得更长；对象一旦结束寿命，那份地址就不再指向任何对象。</p><footer>—— 据 ISO/IEC 9899；Kernighan &amp; Ritchie, The C Programming Language, 2nd ed.；Bryant and O&#39;Hallaron, Computer Systems: A Programmer&#39;s Perspective 整理</footer></div><p>上一课<a href="/cs/integer-overflow">整数溢出</a>把有符号越界收进未定义行为。本课不重讲模算术，也不从垃圾回收另起。缺口是：指针课已经允许一个对象多个名字，栈课已经说明自动对象会消失——<strong>名字还在、对象已死，这算什么</strong>。悬挂是时间上的别名错误。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>对象寿命按存储期走：自动对象在块结束时亡，动态对象在 <code>free</code> 时亡，静态对象在进程结束时亡。指针是独立对象，存着一份地址值。当被指对象亡了，指针值成为不确定的（典型实现里仍是那串比特），再解引用就是 UB；有时连持有该值参与运算也不再安全。缺口因此不是「别忘了 <code>free</code>」，而是<strong>寿命与指针值脱耦</strong>。返回局部数组、<code>free</code> 之后继续用、把栈地址存进全局，都是同一缺口的实例。</p><p>与上一课的别名对照：别名是同一时刻两个名字指向活对象；悬挂是指针落后于寿命。<code>malloc</code>/<code>free</code> 配对错误还会造成泄漏（对象还活，名字丢了）——泄漏通常不是 UB，但会耗尽堆。本课重点在悬挂，泄漏只作为对照。</p><h3 id="释放不是「把字节清零」" tabindex="-1">释放不是「把字节清零」 <a class="header-anchor" href="#释放不是「把字节清零」" aria-label="Permalink to &quot;释放不是「把字节清零」&quot;">​</a></h3><p><code>free(p)</code> 结束动态对象的寿命，并不保证把那片字节写成 0，也不保证 <code>p</code> 变量被改成空。同一地址稍后可以再分配给别人，于是悬挂指针会在「看起来还能用」的数据上读写，造成跨对象破坏。把释放理解成擦除，会漏掉最危险的那种：程序继续跑，数据已属于另一个逻辑对象。</p><p><span class="marginnote">ISO C 用 lifetime 描述对象何时存在。K&amp;R 警告不要返回局部地址。CSAPP 在堆与栈的图上把 use-after-free 画成时间错误。本课不把分配器空闲链表展开。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>规则直觉：指针解引用要求目标此刻活着，且类型匹配。函数返回自动对象的地址必然悬挂。动态对象必须有明确所有者：谁 <code>malloc</code> 谁 <code>free</code>，或把所有权写进接口文档。释放后立即把持有的指针置空，只能防止「同一变量再次误用」，不能修复已经拷贝出去的别名。</p>',11)),(a(),c(E,null,{default:o(()=>[s(t,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20LIVE%5B%22%E5%AF%B9%E8%B1%A1%E6%B4%BB%E7%9D%80%22%5D%20--%3E%20PTR%5B%22%E6%8C%87%E9%92%88%E5%8F%AF%E8%A7%A3%E5%BC%95%E7%94%A8%22%5D%0A%20%20END%5B%22%E5%AF%BF%E5%91%BD%E7%BB%93%E6%9D%9F%22%5D%20--%3E%20DANG%5B%22%E6%8C%87%E9%92%88%E6%82%AC%E6%8C%82%22%5D%0A%20%20DANG%20--%3E%20UB%5B%22%E5%86%8D%E8%A7%A3%E5%BC%95%E7%94%A8%E5%8D%B3%E6%9C%AA%E5%AE%9A%E4%B9%89%22%5D%0A%20%20FREE%5B%22free%20%E5%90%8E%E5%86%8D%E5%88%86%E9%85%8D%22%5D%20--%3E%20ALIAS%5B%22%E5%90%8C%E4%B8%80%E5%9C%B0%E5%9D%80%E5%B1%9E%E4%BA%8E%E6%96%B0%E5%AF%B9%E8%B1%A1%22%5D%0A"})]),fallback:o(()=>[...e[0]||(e[0]=[n(" Loading... ",-1)])]),_:1})),e[2]||(e[2]=r('<p>栈上「内层指向外层」在嵌套调用期间合法，因为外层还活着；返回之后外层也可能已经亡——要分清哪一层的寿命更长。结构体里的指针成员把寿命问题嵌进布局：拷贝结构体只拷贝地址，不延长被指对象的命。</p><p><code>realloc</code> 可能返回新地址并使旧地址寿命结束，所有别名旧指针一起悬挂——这是堆上的集体死亡。接口若返回内部缓冲，必须写明下一次可能使其无效的调用（再 <code>read</code>、再 <code>realloc</code>）。C 库的 <code>strerror</code> 一类函数就有这种「下一次调用使上次指针无效」的契约。后课函数抽象要把这些句子写进头文件注释；只在实现里小心，调用方仍会存下野指针。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>悬挂之所以难查，是因为地址数值仍像合法指针，调试器里还能读到「旧内容」或新对象的内容。发行版里优化器按「不会解引用死对象」改写，症状可以远离真正的 <code>free</code> 点。这与未定义行为课的机制相同，对象换成了寿命。后课 <a href="/cs/raii">RAII</a> 会把资源寿命绑到对象析构，本课先要求在 C 里用纪律模拟同一绑缚。</p><p>诊断上，ASan 把释放后的影子内存标脏，能抓住许多 use-after-free，但仍要求那条路径被执行。编译器也可以把悬挂解引用直接当成不可达而删掉后续代码，使测试「看起来没崩溃」。所以寿命必须写进函数契约，而不是靠一次 sanitizer 绿。栈上返回局部的 bug 在 <code>-O0</code> 里有时还能读到旧值，这是实现残留，不是寿命被延长。后课把「谁在边界上拥有对象」写成函数抽象，正是为了让销毁点唯一。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不讲垃圾回收、不讲代际引用。下一课<a href="/cs/fn-abstraction-boundary">函数作为抽象边界</a>开始把「谁拥有、谁释放」写成接口。后课默认：解引用只对活对象合法；返回局部地址、use-after-free 都是 UB；泄漏不是 UB 但破坏堆资源。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>指针值可长于对象寿命；死后解引用是未定义行为。</li><li><code>free</code> 结束寿命，不擦指针变量，地址可被新对象复用。</li><li>返回自动对象地址必然悬挂；所有权必须写进接口。</li><li>下一课把函数当成声明这些契约的边界。</li><li>出处：ISO C lifetime；K&amp;R；CSAPP 堆与 use-after-free。</li></ul>',9))])}const C=i(p,[["render",f]]);export{g as __pageData,C as default};
